package gui

import (
	"bytes"
	"encoding/base64"
	"image"
	"image/color"
	"image/png"
	"strings"

	"hfsgo/internal/appinfo"
)

func renderModernHTML(logo, donation []byte) string {
	logoURI := ""
	if len(logo) > 0 {
		if compact, err := compactLogoPNG(logo, 192); err == nil {
			logo = compact
		}
		logoURI = "data:image/png;base64," + base64.StdEncoding.EncodeToString(logo)
	}
	donationURI := ""
	if len(donation) > 0 {
		if compact, err := compactLogoPNG(donation, 300); err == nil {
			donation = compact
		}
		donationURI = "data:image/png;base64," + base64.StdEncoding.EncodeToString(donation)
	}
	result := strings.ReplaceAll(modernHTML, "{{LOGO}}", logoURI)
	result = strings.ReplaceAll(result, "{{DONATION}}", donationURI)
	return strings.ReplaceAll(result, "{{VERSION}}", appinfo.Version)
}

func compactLogoPNG(data []byte, maxSize int) ([]byte, error) {
	source, err := png.Decode(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	bounds := source.Bounds()
	width, height := bounds.Dx(), bounds.Dy()
	if width <= 0 || height <= 0 {
		return nil, image.ErrFormat
	}
	if maxSize <= 0 {
		maxSize = 192
	}
	targetWidth, targetHeight := maxSize, maxSize
	if width > height {
		targetHeight = height * maxSize / width
		if targetHeight < 1 {
			targetHeight = 1
		}
	} else if height > width {
		targetWidth = width * maxSize / height
		if targetWidth < 1 {
			targetWidth = 1
		}
	}
	target := image.NewNRGBA(image.Rect(0, 0, targetWidth, targetHeight))
	for y := 0; y < targetHeight; y++ {
		y0 := bounds.Min.Y + y*height/targetHeight
		y1 := bounds.Min.Y + (y+1)*height/targetHeight
		if y1 <= y0 {
			y1 = y0 + 1
		}
		for x := 0; x < targetWidth; x++ {
			x0 := bounds.Min.X + x*width/targetWidth
			x1 := bounds.Min.X + (x+1)*width/targetWidth
			if x1 <= x0 {
				x1 = x0 + 1
			}
			var red, green, blue, alpha uint64
			var count uint64
			for sampleY := y0; sampleY < y1; sampleY++ {
				for sampleX := x0; sampleX < x1; sampleX++ {
					r, g, b, a := source.At(sampleX, sampleY).RGBA()
					red += uint64(r)
					green += uint64(g)
					blue += uint64(b)
					alpha += uint64(a)
					count++
				}
			}
			target.SetNRGBA(x, y, color.NRGBA{
				R: uint8(red / count >> 8),
				G: uint8(green / count >> 8),
				B: uint8(blue / count >> 8),
				A: uint8(alpha / count >> 8),
			})
		}
	}
	var output bytes.Buffer
	if err = png.Encode(&output, target); err != nil {
		return nil, err
	}
	return output.Bytes(), nil
}

